def usl(s):
    return s.isdigit()
l=0
for i in range(len(s)):
    j=i+l+1
    while j<=len(s):
        ss=s[i:j]
        if usl(ss):
            l=len(ss)
            print(i,l,ss)
        else:
            break
        j+=1
print(l)

